// The figure registry and where each figure appears. Figures attach by key rather than as fields on
// the content files: build-journal.json is regenerated by a hook, and build-arcs.json is shared with
// the Artifact generator, so edits there would be overwritten or break a consumer.
import type { DiagramSpec } from "@/components/diagram/types";
import { INTELLIGENCE_ARC_FIGURES } from "./arcs-intelligence";
import { RIGOR_ARC_FIGURES } from "./arcs-rigor";
import { HISTORY_FIGURES } from "./changelog-history";
import { RECENT_FIGURES } from "./changelog-recent";
import { JOURNAL_FIGURES_A } from "./journal-a";
import { JOURNAL_FIGURES_B } from "./journal-b";
import { SYSTEM_FIGURES } from "./system";

export const FIGURES = {
  ...SYSTEM_FIGURES,
  ...INTELLIGENCE_ARC_FIGURES,
  ...RIGOR_ARC_FIGURES,
  ...RECENT_FIGURES,
  ...HISTORY_FIGURES,
  ...JOURNAL_FIGURES_A,
  ...JOURNAL_FIGURES_B,
} satisfies Record<string, DiagramSpec>;

export type FigureId = keyof typeof FIGURES;

/** A figure plus a DOM scope unique to where it's placed (it namespaces the SVG marker ids). */
export type Placed = { id: string; spec: DiagramSpec };

const place = (scope: string, figure: FigureId): Placed => ({ id: `${scope}-${figure}`, spec: FIGURES[figure] });

