export function changelogFigure(date: string, title: string): Placed | null {
  const figure = CHANGELOG[`${date}|${title}`];
  return figure ? place(`changelog-${date}`, figure) : null;
}

export function journalFigures(date: string): Placed[] {
  return (JOURNAL[date] ?? []).map((figure) => place(`journal-${date}`, figure));
}

/** Build arcs share their id with their figure. */
export function arcFigure(arcId: string): Placed | null {
  return arcId in FIGURES ? place("arc", arcId as FigureId) : null;
}

export function pageFigure(scope: string, figure: FigureId): Placed {
  return place(scope, figure);
}
